// Five original hard AgilePM v3 Foundation papers (1–5).
// Official APMG style + syllabus weighting. Not official APMG items.

export const FINAL_MOCKS_A = [
  {
    id: 'final1',
    title: 'Final Paper 1',
    questions: [
      { id: 'F1Q1', topic: 'KC', q: 'Which of the following did the Agile Business Consortium change in the Manifesto wording so it applies beyond software projects?', options: ['It replaced the word software with products', 'It removed the final sentence about items on the right', 'It replaced the word software with solutions', 'It replaced responding to change with following a plan'], correct: 'It replaced the word software with solutions', explain: 'The Consortium broadened software to solutions so the values apply to project value-creation more generally (2.1.3).' },
      { id: 'F1Q2', topic: 'KC', q: 'Identify the missing word. In VUCA, Volatility means things change [ ? ] and unpredictably.', options: ['slowly', 'quickly', 'cyclically', 'linearly'], correct: 'quickly', explain: 'Volatility is rapid, unpredictable change (2.1.2).' },
      { id: 'F1Q3', topic: 'KC', q: 'Which of the following best describes the last responsible moment?', options: ['The point when information is actually needed before the next step is taken', 'The latest date a sponsor will accept a Business Case', 'The final Sprint Review of a Project Increment', 'The moment a Product Backlog item is first written'], correct: 'The point when information is actually needed before the next step is taken', explain: 'Detailed analysis, design and planning are completed when the information is needed, not in advance (2.4.2).' },
      { id: 'F1Q4', topic: 'KC', q: 'Consider the statements about iterative working. Which is/are true?\n1. An iterative approach tests assumptions early so uncertainty can be reduced\n2. An iterative approach removes ambiguity through close collaboration', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Iteration tests assumptions and reduces ambiguity so the right solution can emerge (2.4.2).' },
      { id: 'F1Q5', topic: 'KC', q: 'Which of the following is NOT a reason AgilePM gives for using projects as a delivery mechanism?', options: ['To provide focus and coordination', 'To control investment and resources', 'To organise time-bound outcomes', 'To freeze the solution design before any learning occurs'], correct: 'To freeze the solution design before any learning occurs', explain: 'Projects give focus, coordination and investment control; they are not used to lock design before learning (2.3).' },
      { id: 'F1Q6', topic: 'SC', q: 'Which listed items are among Commitment, Focus, Openness, Respect and Courage?\n1. Openness\n2. Respect\n3. Harmony\n4. Focus', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The five values are Commitment, Focus, Openness, Respect and Courage. Harmony is not one of them (3.3).' },
      { id: 'F1Q7', topic: 'SC', q: 'For a Sprint of one month, which event is timeboxed to a maximum of three hours?', options: ['Sprint Retrospective', 'Sprint Review', 'Sprint Planning', 'Daily Scrum'], correct: 'Sprint Retrospective', explain: 'Retrospective max 3 hours; Review 4 hours; Planning 8 hours; Daily Scrum 15 minutes (3.5).' },
      { id: 'F1Q8', topic: 'SC', q: 'Consider the statements about the Daily Scrum. Which is/are true?\n1. It is the only occasion Developers are allowed to adjust their plan\n2. It is held at the same time and place every working day', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Developers may meet throughout the day; the Daily Scrum is a 15-minute daily inspect-and-adapt event (3.5).' },
      { id: 'F1Q9', topic: 'SC', q: 'Identify the missing word. The Scrum Guide authors warn that although Scrum is lightweight and easy to grasp, it is hard to [ ? ].', options: ['scale', 'teach', 'adopt', 'master'], correct: 'master', explain: 'Scrum is lightweight and simple to understand, but difficult to master (3.1).' },
      { id: 'F1Q10', topic: 'SC', q: 'Which of the following are official Scrum events?\n1. Sprint Planning\n2. Backlog Grooming Workshop\n3. Sprint Review\n4. Daily Scrum', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The five events are the Sprint, Sprint Planning, Daily Scrum, Sprint Review and Sprint Retrospective. Backlog refinement is an activity, not a named event (3.5).' },
      { id: 'F1Q11', topic: 'SC', q: 'Which commitment is attached to the Sprint Backlog?', options: ['Product Goal', 'Sprint Goal', 'Definition of Done', 'Solution Goal'], correct: 'Sprint Goal', explain: 'Product Backlog→Product Goal; Sprint Backlog→Sprint Goal; Increment→Definition of Done (3.6).' },
      { id: 'F1Q12', topic: 'AF', q: 'Identify the missing word. Beneath the four foundational elements, AgilePM is underpinned by common sense and [ ? ].', options: ['pragmatism', 'formality', 'certification', 'documentation'], correct: 'pragmatism', explain: 'Common sense and pragmatism underpin the whole framework (4.1).' },
      { id: 'F1Q13', topic: 'AF', q: 'Which listed items belong in AgilePM\'s eight Rules of Engagement?\n1. Maximise work in progress\n2. Never Compromise Quality\n3. Develop Iteratively\n4. Demonstrate Control', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Never Compromise Quality, Develop Iteratively and Demonstrate Control are three of the eight principles; maximising WIP is not (4.3).' },
      { id: 'F1Q14', topic: 'AF', q: 'Waterfall-style control usually holds which variable still while time and cost are allowed to move?', options: ['Time', 'Cost', 'Features', 'Quality'], correct: 'Features', explain: 'Sequential approaches fix Features and allow Time and Cost to slip; Quality often becomes an accidental variable (4.2).' },
      { id: 'F1Q15', topic: 'AF', q: 'Consider the statements about contingency. Which is/are true?\n1. Parkinson\'s Law states that work expands to fill the time available\n2. AgilePM therefore recommends unused calendar contingency on every estimate', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Parkinson\'s Law is why sponsors hesitate to set time contingency; AgilePM holds contingency in lower-priority features (4.2).' },
      { id: 'F1Q16', topic: 'AF', q: 'Setting and monitoring the Definition of Done for iterations is assigned to which AgilePM role?', options: ['Product Owner', 'Solution Architect', 'Scrum Master', 'Business Sponsor'], correct: 'Solution Architect', explain: 'The Solution Architect sets the Definition of Done for iterations and monitors quality-assurance standards (4.3, Principle 4).' },
      { id: 'F1Q17', topic: 'IN', q: 'Which items appear on the Consortium\'s nine-principle leadership list?\n1. Leadership lives everywhere in the organisation\n2. Leaders devolve appropriate power and authority\n3. People require meaning and purpose to make work fulfilling\n4. Command precedes collaboration', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The first three are leadership principles; command-before-collaboration is the opposite of agile leadership (5.1).' },
      { id: 'F1Q18', topic: 'IN', q: 'Equal decision-making authority is assigned to which trio of AgilePM Project Roles?', options: ['Business Sponsor, Project Manager and Product Owner', 'Business Visionary, Scrum Master and Solution Architect', 'Product Owner, Business Sponsor and Project Manager', 'Business Sponsor, Business Visionary and Solution Architect'], correct: 'Business Sponsor, Business Visionary and Solution Architect', explain: 'Those three Project Roles hold the same level of authority (5.3).' },
      { id: 'F1Q19', topic: 'IN', q: 'Consider the statements about the Product Owner\'s key relationships. Which is/are true?\n1. One of the four is the Business Sponsor\n2. One of the four is the Scrum Master', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Neither 1 nor 2 is true', explain: 'The four are Business Visionary, Solution Architect, Project Manager, and Business and Technical Advisors (5.2.5).' },
      { id: 'F1Q20', topic: 'IN', q: 'Identify the missing words. Geoff Watts\' first commandment for a Scrum Master is [ ? ] the team.', options: ['Direct', 'Replace', 'First ask', 'Report to'], correct: 'First ask', explain: 'The two commandments are First ask the team and Make yourself redundant (5.3.6).' },
      { id: 'F1Q21', topic: 'IN', q: 'Which of the following are Advisor Roles in AgilePM?\n1. Business Advisor\n2. Solution Advisor\n3. Financial Advisor\n4. Process Advisor', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three Advisor Roles are Business, Solution and Process. Financial Advisor is not a defined Advisor Role (5.4).' },
      { id: 'F1Q22', topic: 'IN', q: 'Which role is the Project Champion, owns the Business Case and holds the project budget?', options: ['Business Sponsor', 'Business Visionary', 'Project Manager', 'Product Owner'], correct: 'Business Sponsor', explain: 'The Business Sponsor is the Project Champion, owns the Business Case and holds the budget (5.3).' },
      { id: 'F1Q23', topic: 'IN', q: 'Consider the statements about AgilePM roles. Which is/are true?\n1. A single role may be shared between more than one person\n2. The same person may hold more than one role', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Roles do not necessarily equate to people; sharing and combining roles is allowed (5.3).' },
      { id: 'F1Q24', topic: 'CC', q: 'Which pair of AgilePM principles maps most directly onto working together and exchanging information?', options: ['Focus on the Business Need and Deliver on Time', 'Collaborate and Communicate Continuously and Clearly', 'Never Compromise Quality and Demonstrate Control', 'Build Incrementally from Firm Foundations and Develop Iteratively'], correct: 'Collaborate and Communicate Continuously and Clearly', explain: 'Principles 3 and 7 are Collaborate and Communicate Continuously and Clearly (6.1).' },
      { id: 'F1Q25', topic: 'CC', q: 'Which of the following are listed benefits of collaboration?\n1. Improved problem-solving\n2. Reduced need for a shared purpose\n3. Increased productivity\n4. Cross-functional learning', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Benefits are improved problem-solving, learning, productivity and cross-functional learning. A shared purpose is required, not reduced (6.2).' },
      { id: 'F1Q26', topic: 'CC', q: 'Identify the missing words. On the Power/Interest Grid, a stakeholder with high power and low interest should be [ ? ].', options: ['closely engaged', 'kept informed', 'monitored with minimum effort', 'kept satisfied'], correct: 'kept satisfied', explain: 'High power / low interest → keep satisfied; high/high → closely engage (6.3).' },
      { id: 'F1Q27', topic: 'CC', q: 'Consider the statements about email. Which is/are true?\n1. Email is recommended as the primary method for conveying complex decisions\n2. Email is best used to confirm discussions that have already taken place', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Email confirms previous discussions; it is not the primary method for rich communication (6.3).' },
      { id: 'F1Q28', topic: 'PR', q: 'Which of the following correctly describe increment types in AgilePM?\n1. A Project Increment is the usable output of a single Daily Scrum\n2. A Product Increment is a stepwise refinement of a Product that meets the Definition of Done\n3. A Solution Increment may combine products with training and business-change items\n4. A Project Increment is bound by Foundations at the start and a review at the end', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Product, Solution and Project Increments are distinct; a Daily Scrum does not produce a Project Increment (7.1).' },
      { id: 'F1Q29', topic: 'PR', q: 'Which lifecycle phase decides whether it is even worth investigating a project idea?', options: ['Pre-Project', 'Feasibility', 'Foundations', 'Realisation'], correct: 'Pre-Project', explain: 'Pre-Project asks whether the idea deserves a small investment to explore further (7.2).' },
      { id: 'F1Q30', topic: 'PR', q: 'Consider the statements about Feasibility. Which is/are true?\n1. It examines solution feasibility, stakeholder desirability and people\'s capability to work in an agile way\n2. It is where every requirement is fully specified and baselined', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Feasibility is a light, high-level assessment; fine detail is left later (7.3).' },
      { id: 'F1Q31', topic: 'PR', q: 'Identify the missing word. A [ ? ] is a fixed time period within which a team organises itself to deliver value.', options: ['backlog', 'milestone', 'timebox', 'governance gate'], correct: 'timebox', explain: 'A timebox is a fixed period for organising delivery of value (7.1.2).' },
      { id: 'F1Q32', topic: 'PR', q: 'By the end of Foundations, which of the following should typically have been confirmed?', options: ['Every fine-grained task for the whole project', 'The names of all future users', 'A fully frozen contract specification', 'Whether the solution can be delivered incrementally'], correct: 'Whether the solution can be delivered incrementally', explain: 'Incremental delivery is first explored in Feasibility and confirmed by the end of Foundations (7.2).' },
      { id: 'F1Q33', topic: 'ES', q: 'Which of the following belong to the INVEST model?\n1. Independent\n2. Negotiable\n3. Valuable\n4. Versioned', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'INVEST is Independent, Negotiable, Valuable, Estimable, Small, Testable (8.2.3.4).' },
      { id: 'F1Q34', topic: 'ES', q: 'What approximate share of total effort does AgilePM suggest allocating to Could Have requirements?', options: ['No more than 60%', 'Around 20%', 'Exactly 50%', 'Zero until all Must Haves finish'], correct: 'Around 20%', explain: 'Could Haves are the main contingency pool at about 20% of effort (9.2).' },
      { id: 'F1Q35', topic: 'ES', q: 'Identify the missing word. The Minimum Usable Subset is made up of the [ ? ] Have requirements.', options: ['Must', 'Should', 'Could', 'Won\'t'], correct: 'Must', explain: 'MUST is the Minimum Usable Subset — the Must Haves without which the solution is not viable (9.7).' },
      { id: 'F1Q36', topic: 'ES', q: 'Consider the statements about backlogs and MoSCoW. Which is/are true?\n1. Adding a requirement to a backlog guarantees it will be delivered\n2. MoSCoW mandates the sequence in which requirements must be built', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Neither 1 nor 2 is true', explain: 'A backlog entry is not a delivery promise; MoSCoW describes importance, not build order (8.2, 9.2).' },
      { id: 'F1Q37', topic: 'ES', q: 'Which of the following statements about MoSCoW and the Business Case are true?\n1. Worst-case benefits are based on Must Haves only\n2. Expected-case benefits are based on Could Haves only\n3. Expected-case benefits are based on Musts plus Shoulds\n4. Best-case benefits include Musts, Shoulds and Coulds', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Worst = Musts; expected = Musts+Shoulds; best = Musts+Shoulds+Coulds. Costs cover full scope (9.6).' },
      { id: 'F1Q38', topic: 'ES', q: 'Accountability for MoSCoW priorities that protect the expected return on investment sits primarily with which role?', options: ['Scrum Master', 'Developers', 'Process Advisor', 'Business Visionary'], correct: 'Business Visionary', explain: 'Value Ownership, led by the Business Visionary, ensures priorities protect the expected RoI (9.5).' },
      { id: 'F1Q39', topic: 'PC', q: 'Which of the following is one of AgilePM\'s three planning concepts?', options: ['Management by exception', 'Planning to sensible horizons', 'Transparency of process and progress', 'Responding to change'], correct: 'Planning to sensible horizons', explain: 'The three planning concepts are outcome-based planning, planning to sensible horizons, and planning/re-planning with up-to-date estimates (10.1).' },
      { id: 'F1Q40', topic: 'PC', q: 'Which items sit in AgilePM\'s set of four tracking/control ideas?\n1. Outcome-based measurement\n2. Transparency of process and progress\n3. Fixing all details in Pre-Project\n4. Management by exception', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The four control concepts are outcome-based measurement, transparency, responding to change and management by exception (10.1).' },
      { id: 'F1Q41', topic: 'PC', q: 'Consider the statements about Management by Exception. Which is/are true?\n1. An exception arises if the Delivery Team determines the Sprint Goal is at risk\n2. Exceptions that affect the broader project must be escalated to the Project Manager', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Sprint Goal at risk is a major deviation; broader impacts escalate to the Project Manager (10.4.2).' },
      { id: 'F1Q42', topic: 'PC', q: 'Identify the missing words. Burn-down and burn-up charts are working tools for visibility; they should not be used to [ ? ] team performance.', options: ['judge and compare', 'display remaining work', 'show cumulative flow', 'inspect Sprint progress'], correct: 'judge and compare', explain: 'Charts make progress transparent; they are not for judging or comparing teams (10.4).' },
      { id: 'F1Q43', topic: 'PC', q: 'In a multi-team AgilePM project, who typically facilitates Project Sprint Planning?', options: ['The Product Owner acting alone', 'The Business Sponsor', 'The Project Manager working with Scrum Masters', 'External auditors'], correct: 'The Project Manager working with Scrum Masters', explain: 'The Project Manager and Team Leaders / Scrum Masters facilitate cross-team planning (10.5).' },
      { id: 'F1Q44', topic: 'RK', q: 'Which of the following correctly assign risk ownership?\n1. The Scrum Master owns all Value Ownership risk\n2. The Business Visionary owns Value Ownership-based risk\n3. The Solution Architect owns Solution Delivery-based risk\n4. The Project Manager owns Delivery Enablement risk', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Risk ownership follows the three domains: BV, SA and PM (11.1).' },
      { id: 'F1Q45', topic: 'RK', q: 'The Project Approach Questionnaire is built from how many rated statements?', options: ['17', '8', '12', '4'], correct: '17', explain: 'The PAQ has 17 statements rated on a consensus scale (Appendix B).' },
      { id: 'F1Q46', topic: 'RK', q: 'During which phase is the PAQ typically first completed?', options: ['After the final Deployment', 'During every Daily Scrum', 'In the Feasibility Phase', 'Only if a regulator requests it'], correct: 'In the Feasibility Phase', explain: 'The first PAQ assessment is usually in Feasibility and is reviewed again at the end of Foundations (11.2.1).' },
      { id: 'F1Q47', topic: 'GV', q: 'Identify the missing word. Barry Boehm\'s diagram used in AgilePM financial governance is the Cone of [ ? ].', options: ['Control', 'Uncertainty', 'Compliance', 'Empowerment'], correct: 'Uncertainty', explain: 'The Cone (Core) of Uncertainty shows that early estimates are inherently vague and tighten as the lifecycle progresses (12.3.1).' },
      { id: 'F1Q48', topic: 'GV', q: 'Which of the following are Project Artifacts used for financial governance?\n1. The Business Case\n2. The Feasibility Assessment\n3. The Benefits Assessment\n4. The Daily Scrum', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Financial-governance artifacts include the Feasibility Assessment, Business Case, Foundations Summary, Project Review Report and Benefits Assessment (12.3.2).' },
      { id: 'F1Q49', topic: 'GV', q: 'Consider the statements about single-figure estimates. Which is/are true?\n1. If a Business Sponsor insists on a single figure, the estimator must pick the midpoint\n2. If a Business Sponsor insists on a single figure, the Sponsor must choose it from the range provided', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Sponsor, not the estimator, chooses any single figure from the recommended range (12.3.1).' },
      { id: 'F1Q50', topic: 'GV', q: 'RACI for the Management Approach Definition places Accountability with which role?', options: ['Solution Architect', 'Product Owner', 'Scrum Master', 'Business Sponsor'], correct: 'Business Sponsor', explain: 'MAD: Responsible = Project Manager; Accountable = Business Sponsor (Appendix A).' },
    ],
  },
  {
    id: 'final2',
    title: 'Final Paper 2',
    questions: [
      { id: 'F2Q1', topic: 'KC', q: 'Which of the following best describes Ambiguity in VUCA?', options: ['Things change quickly and unpredictably', 'It is hard to know what will happen or to make accurate predictions', 'Information or situations can have more than one possible meaning', 'Many interconnected parts hide the link between cause and effect'], correct: 'Information or situations can have more than one possible meaning', explain: 'Ambiguity means information can have more than one meaning; Complexity is about unclear cause and effect (2.1.2).' },
      { id: 'F2Q2', topic: 'KC', q: 'What does the Manifesto\'s final sentence emphasise?', options: ['Items on the right have no value and should be discarded', 'Documentation must always be completed before any solution work', 'Items on the right still have value, but we value the items on the left more', 'Contracts are more important than collaboration'], correct: 'Items on the right still have value, but we value the items on the left more', explain: 'The right-hand items remain useful when they add real value and contain just enough detail (2.1.3.5).' },
      { id: 'F2Q3', topic: 'KC', q: 'Identify the missing words. Product development focuses on what a product is and [ ? ] it is designed, built and improved over time.', options: ['how', 'whether', 'when governance signs', 'who funds'], correct: 'how', explain: 'Product development covers the What and the How of building or improving a product (2.2).' },
      { id: 'F2Q4', topic: 'KC', q: 'Consider the statements about Scientific Management. Which is/are true?\n1. Frederick Winslow Taylor promoted efficiency, automation and strict procedure-following\n2. AgilePM treats Taylorism as the preferred operating model for VUCA environments', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Taylorism influenced 20th-century work; its limits (people as operators of systems) are why agility is needed (2.1.1).' },
      { id: 'F2Q5', topic: 'KC', q: 'AgilePM uses which term for potential product value that appears only once the product is actually used?', options: ['Latent value', 'Sunk cost', 'Velocity', 'Scope creep'], correct: 'Latent value', explain: 'A solution-focused view exists so latent value is captured once the product is used (2.2).' },
      { id: 'F2Q6', topic: 'SC', q: 'What must happen to the current Product Goal before the Scrum Team takes on the next one?', options: ['It must be converted into a Sprint Goal', 'It must be signed by the Business Sponsor', 'It must be fulfilled or abandoned', 'It must be added to the Definition of Done'], correct: 'It must be fulfilled or abandoned', explain: 'The Product Goal is the long-term objective and must be fulfilled or abandoned before the next is taken on (3.6).' },
      { id: 'F2Q7', topic: 'SC', q: 'Which of the following are Developer accountabilities in Scrum?\n1. Creating a plan for the Sprint (the Sprint Backlog)\n2. Instilling quality by adhering to the Definition of Done\n3. Owning the Product Goal on behalf of stakeholders\n4. Holding each other accountable as professionals', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Developers plan, instil quality and hold each other accountable; the Product Owner manages the Product Goal (3.4).' },
      { id: 'F2Q8', topic: 'SC', q: 'Identify the missing words. Adaptation becomes more difficult when people are not [ ? ].', options: ['certified as Scrum Masters', 'co-located in one office', 'empowered or self-managing', 'given a fixed specification'], correct: 'empowered or self-managing', explain: 'Adaptation should occur as soon as possible and is harder without empowerment (3.2).' },
      { id: 'F2Q9', topic: 'SC', q: 'Consider the statements about cancelling a Sprint. Which is/are true?\n1. Any stakeholder may cancel a Sprint if they dislike the forecast\n2. Only the Product Owner can cancel a Sprint, and only if the Sprint Goal becomes obsolete', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Cancellation is solely the Product Owner\'s decision when the Sprint Goal is obsolete (3.5).' },
      { id: 'F2Q10', topic: 'SC', q: 'To stay nimble while still finishing significant work, a Scrum Team is typically kept to what size?', options: ['15 or fewer people', 'Exactly 7 people', '10 or fewer people', 'No guidance is given'], correct: '10 or fewer people', explain: 'A Scrum Team is typically 10 or fewer — small enough to stay nimble, large enough to complete significant work (3.4).' },
      { id: 'F2Q11', topic: 'SC', q: 'Which of these are the three artifacts defined by Scrum (AgilePM names the third Product Increment)?\n1. Product Backlog\n2. Sprint Backlog\n3. Delivery Plan\n4. Product Increment', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The three Scrum artifacts are Product Backlog, Sprint Backlog and Increment (Product Increment in AgilePM) (3.6).' },
      { id: 'F2Q12', topic: 'AF', q: 'Roles and responsibilities sit under which of the four foundational elements of the AgilePM Framework?', options: ['Process', 'Practices', 'People', 'Project Artifacts'], correct: 'People', explain: 'The four elements are Process, People, Project Artifacts and Practices; People covers roles (4.1).' },
      { id: 'F2Q13', topic: 'AF', q: 'Consider the statements about AgilePM principles versus the Manifesto. Which is/are true?\n1. Demonstrate Control is one of AgilePM\'s eight principles\n2. Demonstrate Control is one of the four Manifesto values', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Demonstrate Control is AgilePM Principle 8, not a Manifesto value (4.3 / 2.1.3).' },
      { id: 'F2Q14', topic: 'AF', q: 'Identify the missing words. Under Focus on the Business Need, every decision should be evaluated against the [ ? ].', options: ['project vision', 'Sprint Backlog only', 'supplier contract clause', 'Daily Scrum agenda'], correct: 'project vision', explain: 'Principle 1 requires every decision to be made with the project vision in mind (4.3).' },
      { id: 'F2Q15', topic: 'AF', q: 'Which of the following does AgilePM combined with Scrum provide?\n1. A project lifecycle with appropriate governance\n2. Additional roles ensuring value delivery in a corporate context\n3. A rule that Scrum events may be dropped if inconvenient\n4. Techniques to help deliver on time and within budget', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'AgilePM adds lifecycle, extra roles and time/budget techniques; Scrum\'s events remain essential (4.4).' },
      { id: 'F2Q16', topic: 'AF', q: 'How does AgilePM typically hold contingency, rather than adding unused time or budget?', options: ['By extending every Sprint to two months', 'By hiding a secret management reserve from the team', 'By freezing quality until the last increment', 'By using MoSCoW so lower-priority features can be dropped'], correct: 'By using MoSCoW so lower-priority features can be dropped', explain: 'Contingency lives in feature scope via MoSCoW, not in slack time or cost (4.2).' },
      { id: 'F2Q17', topic: 'IN', q: 'Identify the missing words. The first principle of Agile Leadership is that leadership lives [ ? ] in the organisation.', options: ['only in the PMO', 'outside delivery teams', 'solely with the sponsor', 'everywhere'], correct: 'everywhere', explain: 'Leadership lives everywhere and may emerge from expertise and initiative (5.1).' },
      { id: 'F2Q18', topic: 'IN', q: 'The Product Owner\'s four standing relationships include which of the following people?\n1. Business Visionary\n2. Solution Architect\n3. Business and Technical Advisors\n4. Business Sponsor', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The four are BV, SA, PM and Business & Technical Advisors — not the Business Sponsor (5.2.5).' },
      { id: 'F2Q19', topic: 'IN', q: 'Which domain does the Project Manager belong to?', options: ['Value Ownership', 'Solution Delivery', 'Delivery Enablement', 'External Assurance'], correct: 'Delivery Enablement', explain: 'The three domains are Value Ownership, Solution Delivery and Delivery Enablement; the PM leads Delivery Enablement (5.3).' },
      { id: 'F2Q20', topic: 'IN', q: 'A scaled Team Leader / Scrum Master arrangement is described as follows. Which is/are true?\n1. An experienced Scrum Master may support up to three teams\n2. The Scrum Master directs the day-to-day technical work of Developers', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'An experienced Scrum Master may support up to three teams; they coach rather than direct technical work (5.3.6).' },
      { id: 'F2Q21', topic: 'IN', q: 'Which Project Role is expected to keep the Business Visionary\'s ambition realistic so the design stays feasible?', options: ['Business Sponsor', 'Process Advisor', 'Product Owner', 'Solution Architect'], correct: 'Solution Architect', explain: 'The Solution Architect owns solution design and balances ambition with feasibility (5.3).' },
      { id: 'F2Q22', topic: 'IN', q: 'Engagement with people outside the project organisation is shaped by which factors?\n1. Purpose\n2. Timing\n3. Authority\n4. Favourite programming language', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The four factors are Purpose, Timing, Authority and Constraints (5.2).' },
      { id: 'F2Q23', topic: 'IN', q: 'Identify the missing word. AgilePM uses the word Developers not to exclude people, but to [ ? ].', options: ['simplify', 'grade seniority', 'replace the Product Owner', 'avoid cross-functionality'], correct: 'simplify', explain: 'The title is used to simplify; teams still need diverse skills (5.4).' },
      { id: 'F2Q24', topic: 'CC', q: 'Consider the statements about the Aligned Autonomy Matrix. Which is/are true?\n1. High alignment and high autonomy describes an innovative, collaborative culture\n2. High alignment and low autonomy describes a chaotic entrepreneurial culture', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'High/High = Innovative (Collaborative); High/Low = Authoritative; Low/High = Entrepreneurial/Chaotic (6.3).' },
      { id: 'F2Q25', topic: 'CC', q: 'In a Facilitated Workshop, the independent facilitator (a Process Advisor) is there to do which of the following?', options: ['Own the business vision and decide the outcome', 'Write the Management Approach Definition', 'Estimate every user story in the room', 'Run the process so the defined outcome is reached and everyone can contribute'], correct: 'Run the process so the defined outcome is reached and everyone can contribute', explain: 'The facilitator is a Process Advisor who runs the process, not the content (6.4).' },
      { id: 'F2Q26', topic: 'CC', q: 'Projects often fail when communication breaks down. Which of these are listed failure modes?\n1. Not using a shared language\n2. Lack of access to the right people at the right time\n3. Over-reliance on written communication\n4. Preferring face-to-face conversation for complex issues', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Face-to-face is recommended, not a failure; the others are listed failure modes (6.1.2).' },
      { id: 'F2Q27', topic: 'CC', q: 'Identify the missing word. Community collaboration promotes a sense of [ ? ] among all teams delivering value.', options: ['rivalry', 'hierarchy', 'secrecy', 'unity'], correct: 'unity', explain: 'Community collaboration promotes unity across teams and organisational boundaries (6.2).' },
      { id: 'F2Q28', topic: 'PR', q: 'Starting from the first decision to investigate an idea, which sequence of phases does the AgilePM Process Model follow?', options: ['Feasibility, Pre-Project, Delivery, Foundations, Realisation, Deployment', 'Pre-Project, Delivery, Feasibility, Foundations, Realisation, Deployment', 'Foundations, Feasibility, Pre-Project, Deployment, Delivery, Realisation', 'Pre-Project, Feasibility, Foundations, Delivery, Deployment, Realisation'], correct: 'Pre-Project, Feasibility, Foundations, Delivery, Deployment, Realisation', explain: 'The Process Model is Pre-Project → Feasibility → Foundations → Delivery → Deployment → Realisation (7.2).' },
      { id: 'F2Q29', topic: 'PR', q: 'Consider the statements about Foundations duration. Which is/are true?\n1. Fine details are deliberately left for the Delivery Phase\n2. Foundations should last many months even on a simple project so every requirement can be fully specified', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Keeping scope high-level helps Foundations last only a few weeks, even for large projects (7.4).' },
      { id: 'F2Q30', topic: 'PR', q: 'Which of the following correctly describe Feasibility artifacts?\n1. The Business Case is Recommended\n2. The Product Backlog is Required by the end of Feasibility\n3. The Solution Backlog is Optional\n4. The Management Approach Definition is Recommended', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Business Case and MAD are Recommended; Solution Backlog is Optional. The Product Backlog is Required by the end of Foundations, not Feasibility (7.3).' },
      { id: 'F2Q31', topic: 'PR', q: 'A Solution Increment is best described as which of the following?', options: ['The output of a single Daily Scrum', 'Only the source code produced by one Developer', 'A stepwise refinement of the overall Solution, which may include products plus training and business change', 'A synonym for the Project Timebox'], correct: 'A stepwise refinement of the overall Solution, which may include products plus training and business change', explain: 'A Solution Increment meets the overarching outcome and may combine multiple products and other items (7.1).' },
      { id: 'F2Q32', topic: 'PR', q: 'Identify the missing word. Each Project Increment is bound at the start by revisiting [ ? ] and at the end by a review.', options: ['Pre-Project', 'Deployment', 'Foundations', 'Realisation only'], correct: 'Foundations', explain: 'Project Increment timeboxes are bound by Foundations at the start and a Project Increment Review at the end (7.1.2).' },
      { id: 'F2Q33', topic: 'ES', q: 'Consider the statements about User Story composition. Which is/are true?\n1. The Three Cs are Card, Conversation and Confirmation\n2. Contract is one of the Three Cs', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'The Three Cs are Card, Conversation and Confirmation; Contract is a common trap (8.2.3.3).' },
      { id: 'F2Q34', topic: 'ES', q: 'Which of the following are true of relative estimation?\n1. Relative estimates replace the need for a Definition of Done\n2. T-shirt sizes and story points both focus on relative effort rather than exact hours\n3. Story points allow people of different skill levels to participate equally\n4. Both styles use a scale rather than a single clock-time figure', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Relative estimates compare effort; they do not replace quality agreements such as the DoD (8.3).' },
      { id: 'F2Q35', topic: 'ES', q: 'The common story phrasing that states the user, the need and the benefit is most closely associated with which author?', options: ['Ken Schwaber', 'Frederick Taylor', 'Barry Boehm', 'Mike Cohn'], correct: 'Mike Cohn', explain: 'The widely used As a / I want / So that format is associated with Mike Cohn (8.2.3.1).' },
      { id: 'F2Q36', topic: 'ES', q: 'Identify the missing words. AgilePM recommends that cost estimates cover [ ? ], while benefit estimates are based on Musts plus Shoulds.', options: ['full scope', 'Must Haves only', 'Could Haves only', 'Won\'t Haves only'], correct: 'full scope', explain: 'Costs cover the full planned scope; benefits for the expected case are Musts + Shoulds (9.6).' },
      { id: 'F2Q37', topic: 'ES', q: 'When a project is high risk, what should typically happen to the Must Have effort share?', options: ['It should be increased above 80%', 'Must Haves should be abandoned', 'It must stay at exactly 60%', 'It should be reduced below the usual level'], correct: 'It should be reduced below the usual level', explain: 'If risk is high, reduce Must Have effort further to keep enough contingency (9.2).' },
      { id: 'F2Q38', topic: 'ES', q: 'Which of the following are true about Won\'t Have this time?\n1. Documenting them helps prevent unspoken scope from returning later\n2. They are permanently forbidden on every future project\n3. They free capacity for higher-priority work in this timeframe\n4. They still describe work that was considered', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Won\'t Have this time is for this timeframe; documenting them manages expectations and capacity (9.2).' },
      { id: 'F2Q39', topic: 'PC', q: 'Identify the missing word. A planning [ ? ] is how far ahead a plan is intended to remain useful before it is revisited.', options: ['horizon', 'contract', 'increment backlog', 'exception'], correct: 'horizon', explain: 'Planning to sensible horizons means planning only as far as the information supports (10.2).' },
      { id: 'F2Q40', topic: 'PC', q: 'At project scale, Cross-Team Refinement exists mainly to achieve which of the following?', options: ['Writing the Business Sponsor\'s personal objectives', 'Approving supplier invoices', 'Replacing the Sprint Retrospective', 'Aligning upcoming work and dependencies across Delivery Teams'], correct: 'Aligning upcoming work and dependencies across Delivery Teams', explain: 'CTR aligns teams, backlogs and dependencies at project scale (10.5).' },
      { id: 'F2Q41', topic: 'PC', q: 'Sprint Planning is structured around three questions. Which set is correct?\n1. Why is this Sprint valuable?\n2. What can be Done this Sprint?\n3. Who should be blamed for last Sprint?\n4. How will the chosen work get done?', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'The three topics are Why, What and How — not blame (3.5 / 10.6).' },
      { id: 'F2Q42', topic: 'PC', q: 'Consider the statements about burn-down charts. Which is/are true?\n1. They should be used as the sole basis for comparing team performance\n2. They are working tools that make remaining work visible', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Charts support transparency; they must not be used to judge or compare teams (10.4).' },
      { id: 'F2Q43', topic: 'PC', q: 'To keep the conversation candid, the Project Sprint Retrospective is for the Project Organisation rather than which audience?', options: ['Scrum Masters', 'Developers', 'Product Owners', 'The wider stakeholder audience from the Project Sprint Review'], correct: 'The wider stakeholder audience from the Project Sprint Review', explain: 'The Project Sprint Retrospective is for the Project Organisation / teams, not a public stakeholder show (10.5).' },
      { id: 'F2Q44', topic: 'RK', q: 'Identify the missing word. Disagreement with a PAQ statement is treated as a [ ? ] that the default approach may not work as-is.', options: ['guarantee', 'reason to skip Foundations', 'celebration', 'risk'], correct: 'risk', explain: 'Disagreement with a PAQ statement signals approach risk that must be resolved or tailored (11.2.1).' },
      { id: 'F2Q45', topic: 'RK', q: 'Team members rate each PAQ statement using which kind of scale?', options: ['Pass or fail only', 'Fibonacci story points', 'A consensus opinion from Strongly Agree to Strongly Disagree', 'Red, amber, green assigned by auditors'], correct: 'A consensus opinion from Strongly Agree to Strongly Disagree', explain: 'The 17 statements use a Strongly Agree–Strongly Disagree consensus scale (Appendix B).' },
      { id: 'F2Q46', topic: 'RK', q: 'Consider the statements about VUCA-related risk. Which is/are true?\n1. AgilePM treats risk management as fully integrated into day-to-day execution\n2. A separate formal risk process is usually required on every simple AgilePM project', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Risk is integrated; a separate formal process is usually needed only in highly regulated or safety contexts (11.1).' },
      { id: 'F2Q47', topic: 'GV', q: 'Traditional compliance-heavy governance is sometimes described as the Manifesto in reverse because it favours which of the following?', options: ['Individuals and interactions over processes and tools', 'Working solutions over comprehensive documentation', 'Processes and tools over individuals and interactions', 'Responding to change over following a plan'], correct: 'Processes and tools over individuals and interactions', explain: 'Inappropriate governance emphasises the right-hand Manifesto items (12.1.1).' },
      { id: 'F2Q48', topic: 'GV', q: 'Governance and empiricism are sometimes treated as opposites. Which is/are true?\n1. They are fundamentally incompatible and cannot coexist\n2. Governance can support empiricism if designed around purpose rather than ritual', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Definitions do not conflict; governance should focus on purpose without blocking agility (12.1).' },
      { id: 'F2Q49', topic: 'GV', q: 'Which of the following are Required evolutionary artifacts during delivery?\n1. Solution Backlog\n2. Product Backlog\n3. Sprint Backlog\n4. Delivery Plan', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Product Backlog, Sprint Backlog and Delivery Plan are Required; the Solution Backlog is Optional (Appendix A).' },
      { id: 'F2Q50', topic: 'GV', q: 'RACI for a Product Increment assigns which pairing?', options: ['Responsible: Project Manager; Accountable: Business Sponsor', 'Responsible: Developers; Accountable: Business Visionary', 'Responsible: Scrum Master; Accountable: Solution Architect', 'Responsible: Delivery Team; Accountable: Product Owner'], correct: 'Responsible: Delivery Team; Accountable: Product Owner', explain: 'Product Increment R = Delivery Team, A = Product Owner (Appendix A).' },
    ],
  },
  {
    id: 'final3',
    title: 'Final Paper 3',
    questions: [
      { id: 'F3Q1', topic: 'KC', q: 'Which of the following best describes Complexity in VUCA?', options: ['Things change quickly and unpredictably', 'Information can have more than one meaning', 'Many interconnected parts make cause and effect unclear', 'It is hard to know what will happen next'], correct: 'Many interconnected parts make cause and effect unclear', explain: 'Complexity is about interconnected parts hiding cause and effect; Uncertainty is about prediction (2.1.2).' },
      { id: 'F3Q2', topic: 'KC', q: 'Using the Consortium wording (solutions, not software), which value statements are genuine?\n1. Individuals and interactions over processes and tools\n2. Working solutions over comprehensive documentation\n3. Comprehensive contracts over customer collaboration\n4. Responding to change over following a plan', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'The third value is customer collaboration over contract negotiation — the listed item is reversed (2.1.3).' },
      { id: 'F3Q3', topic: 'KC', q: 'Consider the statements about project management versus product development. Which is/are true?\n1. Project management takes a wider view, organising the environment so delivered value is actually achieved\n2. Product development is only concerned with portfolio funding gates', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Product development covers what a product becomes and how it is built; project management oversees the wider environment and realisation of value (2.2–2.3).' },
      { id: 'F3Q4', topic: 'KC', q: 'Identify the missing word. People and systems that cope best with VUCA are flexible, adaptable, thoughtful, collaborative and good at solving [ ? ].', options: ['contracts', 'hierarchies', 'problems', 'timesheets'], correct: 'problems', explain: 'AgilePM lists flexibility, adaptability, thoughtfulness, collaboration and problem-solving as VUCA-coping traits (2.1.2).' },
      { id: 'F3Q5', topic: 'KC', q: 'Which of the following is NOT a listed aspect of project management in AgilePM\'s Who / Why / When / Where model?', options: ['Who: people, teams and structures', 'Why: purpose, value and business case', 'When: timeframes, events and deliveries', 'Whether: a guaranteed profit figure before Feasibility'], correct: 'Whether: a guaranteed profit figure before Feasibility', explain: 'The key aspects are Who, Why, When and Where — not a guaranteed profit before investigation (2.3).' },
      { id: 'F3Q6', topic: 'SC', q: 'Which pair of ideas underpins Scrum theory?', options: ['Empiricism and lean thinking', 'Detailed upfront specification and stage gates', 'Individual heroics and overtime', 'Fixed scope contracts only'], correct: 'Empiricism and lean thinking', explain: 'Scrum is founded on empiricism (knowledge from experience) and lean thinking (reduce waste) (3.2).' },
      { id: 'F3Q7', topic: 'SC', q: 'The last inspection of the Increment before the Retrospective is described as follows. Which is/are true?\n1. It should be limited to a slide presentation with no discussion\n2. It is a working session in which the Scrum Team and stakeholders inspect the outcome and adapt', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Sprint Review is a working session, not merely a presentation (3.5).' },
      { id: 'F3Q8', topic: 'SC', q: 'Which of the following are true of the Product Backlog?\n1. It is the single source of work for the Scrum Team\n2. Its commitment is the Product Goal\n3. It is owned and ordered by the Scrum Master\n4. Refinement breaks items into smaller, more precise items', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Product Owner manages and orders the Product Backlog; the Scrum Master does not own it (3.6).' },
      { id: 'F3Q9', topic: 'SC', q: 'If the Sprint lasts a full month, Sprint Planning must finish within what upper limit?', options: ['15 minutes', '3 hours', '4 hours', '8 hours'], correct: '8 hours', explain: 'Sprint Planning is timeboxed to a maximum of 8 hours for a one-month Sprint (3.5).' },
      { id: 'F3Q10', topic: 'SC', q: 'Identify the missing word. Inspection without [ ? ] is considered pointless.', options: ['adaptation', 'documentation', 'a steering committee', 'a Gantt chart'], correct: 'adaptation', explain: 'Inspection enables adaptation; inspection without adaptation is pointless (3.2).' },
      { id: 'F3Q11', topic: 'SC', q: 'Which of the following correctly pair a Scrum artifact with its commitment?\n1. Product Backlog — Product Goal\n2. Sprint Backlog — Sprint Goal\n3. Product Increment — Definition of Done\n4. Sprint Backlog — Product Goal', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Sprint Backlog commits to the Sprint Goal, not the Product Goal (3.6).' },
      { id: 'F3Q12', topic: 'AF', q: 'Which AgilePM principle warns that a delayed Solution Increment can lose its value, especially around market or legal deadlines?', options: ['Focus on the Business Need', 'Never Compromise Quality', 'Deliver on Time', 'Demonstrate Control'], correct: 'Deliver on Time', explain: 'Principle 2 stresses on-time delivery because delayed increments can lose value (4.3).' },
      { id: 'F3Q13', topic: 'AF', q: 'Which of the following are among AgilePM\'s five practices?\n1. Iterative Development\n2. Timeboxing\n3. Fixed-scope contract negotiation\n4. MoSCoW Prioritisation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The five practices are Iterative Development, Timeboxing, MoSCoW, Modelling and Facilitated Workshops (4.3).' },
      { id: 'F3Q14', topic: 'AF', q: 'Consider the statements about quality. Which is/are true?\n1. Expected quality should be defined at the beginning of the project\n2. Fit-for-purpose means the solution should far exceed business needs regardless of cost', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Never Compromise Quality means good enough to meet the need — not exceeding or falling short (4.3).' },
      { id: 'F3Q15', topic: 'AF', q: 'Who creates the Business Case, and what must the Project Manager do with it?', options: ['The Project Manager writes it; the Scrum Master funds it', 'Developers write it during the Daily Scrum', 'Value Ownership roles own it; the Project Manager must ensure it receives appropriate attention', 'The Process Advisor is solely accountable for benefits'], correct: 'Value Ownership roles own it; the Project Manager must ensure it receives appropriate attention', explain: 'The PM does not create the Business Case but must keep attention on it throughout (4.3).' },
      { id: 'F3Q16', topic: 'AF', q: 'The AgilePM Framework is described as resting on four named elements. Which of the following sits outside that set of four?', options: ['Process', 'People', 'Practices', 'A procurement-auction layer'], correct: 'A procurement-auction layer', explain: 'The four elements are Process, People, Project Artifacts and Practices (4.1).' },
      { id: 'F3Q17', topic: 'IN', q: 'Which of these statements are real Agile Leadership principles rather than plan-driven slogans?\n1. Actions speak louder than words\n2. Improved quality of thinking leads to improved outcomes\n3. Fixed plans deliver predictable results\n4. Organisations improve through effective feedback', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Fixed plans delivering predictable results is not a leadership principle (5.1).' },
      { id: 'F3Q18', topic: 'IN', q: 'What decisions does the Business Visionary make, as distinct from the Solution Architect and Project Manager?', options: ['How the project is managed day to day', 'The integrity of the technical architecture alone', 'Business-value-related decisions', 'Cancellation of every Sprint'], correct: 'Business-value-related decisions', explain: 'BV decides business value; SA decides solution integrity; PM decides how the project is managed (5.3).' },
      { id: 'F3Q19', topic: 'IN', q: 'Consider the statements about empowerment. Which is/are true?\n1. Empowerment requires people to be capable, willing and informed\n2. Boundaries of empowerment describe how much authority someone has before extra approval is needed', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Capable, willing and informed are the empowerment conditions; boundaries set the limits of discretion (2.1.3 / 5.1).' },
      { id: 'F3Q20', topic: 'IN', q: 'The Project Manager is expected to sustain collaborative links with which group of people?', options: ['Only the Process Advisor, excluding all Project Roles', 'External regulators to the exclusion of the Delivery Team', 'The Daily Scrum attendees only', 'Business Sponsor, Business Visionary, Solution Architect, Product Owner, Scrum Master and other stakeholders'], correct: 'Business Sponsor, Business Visionary, Solution Architect, Product Owner, Scrum Master and other stakeholders', explain: 'The PM maintains those six relationship groups (5.5).' },
      { id: 'F3Q21', topic: 'IN', q: 'Identify the missing words. True leadership, as restated in the Scrum Guide, is shown when success is defined by the [ ? ] of the Delivery Team(s).', options: ['overtime hours', 'document count', 'headcount', 'effectiveness'], correct: 'effectiveness', explain: 'True leadership develops others; success is the team\'s effectiveness (5.3.6).' },
      { id: 'F3Q22', topic: 'IN', q: 'Which of the following correctly describe Advisor Roles?\n1. A Business Advisor provides specialist business input on requirements and compliance\n2. A Solution Advisor provides specialist, often technical, input on design and operations\n3. A Process Advisor may be an Agile Coach or Workshop Facilitator\n4. A Financial Advisor is the fourth named Advisor Role', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'There are three Advisor Roles: Business, Solution and Process (5.4).' },
      { id: 'F3Q23', topic: 'IN', q: 'Who should manage relationships with external stakeholders, facilitated by the Project Manager?', options: ['The Scrum Master and Developers only', 'Anyone who happens to send an email', 'The Process Advisor acting alone', 'The Business Visionary and Solution Architect'], correct: 'The Business Visionary and Solution Architect', explain: 'BV and SA manage those relationships; the PM facilitates (5.2).' },
      { id: 'F3Q24', topic: 'CC', q: 'AgilePM lists empathy, adaptability and resilience as collaboration skills. Which of the following is the opposite of that list?', options: ['Problem-solving', 'Reliability', 'Teamwork', 'Unilateral blame'], correct: 'Unilateral blame', explain: 'Listed soft skills include creativity, empathy, problem-solving, adaptability, reliability, resilience, leadership, teamwork and communication (6.1.1).' },
      { id: 'F3Q25', topic: 'CC', q: 'Consider the statements about face-to-face communication. Which is/are true?\n1. The Manifesto calls face-to-face the most efficient and effective method within a team\n2. Virtual meetings can be nearly as effective if video and audio quality are reliable', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Face-to-face is preferred; good virtual meetings can be nearly as effective (2.1.4 / 6.3).' },
      { id: 'F3Q26', topic: 'CC', q: 'Identify the missing word. Active listening includes paying attention, showing you are listening, deferring [ ? ] until the speaker has finished, then responding appropriately.', options: ['judgment', 'funding', 'the Sprint Goal', 'MoSCoW'], correct: 'judgment', explain: 'Active listening defers judgment until the speaker has finished (6.3).' },
      { id: 'F3Q27', topic: 'CC', q: 'AgilePM judges a document successful primarily when it achieves which outcome?', options: ['The longest possible page count', 'A permanent freeze on requirements', 'Replacement of all conversation', 'A shared understanding of the content among those who use it'], correct: 'A shared understanding of the content among those who use it', explain: 'Shared understanding matters more than the document as an object (6.4).' },
      { id: 'F3Q28', topic: 'PR', q: 'Identify the missing words. A Product Increment is delivered by one or more [ ? ].', options: ['investment boards', 'Daily Scrum minutes', 'external regulators', 'Agile Delivery Teams'], correct: 'Agile Delivery Teams', explain: 'Product Increments come from Delivery Teams; Solution Increments meet the overarching outcome (7.1).' },
      { id: 'F3Q29', topic: 'PR', q: 'After a Solution Increment is in live use, which phase checks that predicted business value is actually appearing?', options: ['Pre-Project', 'Sprint Planning', 'Feasibility', 'Realisation'], correct: 'Realisation', explain: 'Realisation checks that predicted value actually appears in operation (7.2 / 7.7).' },
      { id: 'F3Q30', topic: 'PR', q: 'AgilePM\'s meaning of Solution includes which of the following ideas?\n1. It may include products, services, processes and people\n2. It only ever consists of a single Product Increment from one team\n3. Increments of several products may combine into a Solution Increment\n4. When a Solution Increment is deployed it becomes or adds to the Deployed Solution', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'A Solution is broader than one product and one team (7.1).' },
      { id: 'F3Q31', topic: 'PR', q: 'Consider the statements about lifecycle configuration. Which is/are true?\n1. Every project must use continuous deployment multiple times per Sprint\n2. AgilePM describes several configurations, from a single Project Increment to continuous delivery', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Examples range from a simple single increment to multi-increment and continuous delivery (7.2).' },
      { id: 'F3Q32', topic: 'PR', q: 'During Feasibility, roughly how accurate are cost estimates expected to be?', options: ['Exact to the nearest hour', 'Accurate enough to freeze all features', 'Zero uncertainty after one workshop', 'About +/- 50%'], correct: 'About +/- 50%', explain: 'Only rough cost estimates are needed at Feasibility (e.g. +/- 50%) (7.3).' },
      { id: 'F3Q33', topic: 'ES', q: 'Which of the following are suggested Definition of Ready ideas?\n1. The item is small enough to complete in a Sprint\n2. The Business Sponsor has personally coded a prototype\n3. Acceptance Criteria are understood\n4. Dependencies that would block the item are known', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'DoR is about readiness for planning; it does not require the Sponsor to build a prototype (8.2).' },
      { id: 'F3Q34', topic: 'ES', q: 'What does INVEST\'s E stand for?', options: ['Evolutionary', 'Exception', 'External', 'Estimable'], correct: 'Estimable', explain: 'INVEST = Independent, Negotiable, Valuable, Estimable, Small, Testable (8.2.3.4).' },
      { id: 'F3Q35', topic: 'ES', q: 'Consider the statements about estimating responsibility. Which is/are true?\n1. The people doing the work are responsible for estimating it\n2. Overly detailed early estimates become more accurate simply because they contain more numbers', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Those who do the work estimate; extra early detail can create false precision (8.3).' },
      { id: 'F3Q36', topic: 'ES', q: 'Why do Planning Poker decks usually jump in a Fibonacci-like way rather than in equal hours?', options: ['To hide uncertainty from the Sponsor', 'Because uncertainty grows faster than a linear hour scale suggests', 'Because only powers of two are allowed in Scrum', 'Because the number of stakeholders must equal the estimate'], correct: 'Because uncertainty grows faster than a linear hour scale suggests', explain: 'Planning Poker commonly uses a Fibonacci-like scale to reflect growing uncertainty (8.3).' },
      { id: 'F3Q37', topic: 'ES', q: 'Identify the missing word. Estimating by analogy is also known as estimating by [ ? ].', options: ['comparison', 'decomposition', 'contract', 'exception'], correct: 'comparison', explain: 'Analogy (comparison) and decomposition (breaking down) are complementary styles (8.3).' },
      { id: 'F3Q38', topic: 'ES', q: 'At Product Increment level, which statements correctly describe Could Have work?\n1. It acts as a buffer and the main pool of contingency\n2. It is guaranteed to be delivered if the project starts\n3. About 20% of effort is typically allocated to Could Haves\n4. Could Haves are dropped first when problems occur', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Could Haves are not guaranteed; they are the first contingency (9.2–9.3).' },
      { id: 'F3Q39', topic: 'PC', q: 'Bottlenecks in flow are most clearly revealed by which chart, which plots work-item status bands over time?', options: ['A burn-down of remaining hours only', 'A burn-up of scope completed only', 'A cumulative flow diagram', 'A Gantt baseline with no WIP view'], correct: 'A cumulative flow diagram', explain: 'A CFD shows status bands over time and highlights bottlenecks (10.4).' },
      { id: 'F3Q40', topic: 'PC', q: 'AgilePM nests plans at which three time horizons?\n1. Project\n2. Project Increment\n3. Individual annual appraisal\n4. Sprint / Delivery Timebox', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Planning nests at project, Project Increment and Sprint levels (10.2).' },
      { id: 'F3Q41', topic: 'PC', q: 'Consider the statements about outcome-based measurement. Which is/are true?\n1. An Increment is an output; the outcome is realised when the product is used in operation\n2. Counting completed tasks is preferred to measuring value delivered', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Progress is measured by value delivered, not task counts (10.4.1).' },
      { id: 'F3Q42', topic: 'PC', q: 'If a Delivery Team cannot demonstrate a complete Product Increment at the end of a Sprint, what should they do first?', options: ['Hide the Sprint from stakeholders', 'Improve discipline, integration or testing so each Sprint produces something usable, and still show whatever progress is real', 'Automatically extend the Sprint until everything is perfect', 'Replace MoSCoW with a fixed specification'], correct: 'Improve discipline, integration or testing so each Sprint produces something usable, and still show whatever progress is real', explain: 'PAQ 16: even if a complete increment cannot be shown, teams should still demonstrate real progress (11.2.2).' },
      { id: 'F3Q43', topic: 'PC', q: 'Multiple Delivery Teams inspect shared progress and dependencies in which scaled coordination event?', options: ['A meeting that replaces the Product Owner', 'A Scrum of Scrums', 'A Terms of Reference workshop', 'A decision to cancel Foundations'], correct: 'A Scrum of Scrums', explain: 'SoS is a scaled coordination event across teams (10.5).' },
      { id: 'F3Q44', topic: 'RK', q: 'Identify the missing words. The PAQ is designed to highlight risk associated with both the project\'s objective and the [ ? ] used in its delivery.', options: ['office lease', 'agile way of working', 'holiday rota', 'brand colour palette'], correct: 'agile way of working', explain: 'The PAQ addresses goal risk and approach risk so the method can be tailored (11.2.1).' },
      { id: 'F3Q45', topic: 'RK', q: 'Consider PAQ Statement 2. Which is/are true?\n1. The Business Sponsor and Business Visionary must demonstrate clear, proactive ownership\n2. If coaching fails to engage the Business Visionary, AgilePM says to continue anyway and hope for the best', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'If ownership cannot be engaged, the recommended action is to refuse to continue until it is resolved (11.2.2).' },
      { id: 'F3Q46', topic: 'RK', q: 'Organisation, schedule and dependency risk in the Delivery Enablement domain is owned by which role?', options: ['Business Visionary', 'Solution Architect', 'Project Manager', 'Product Owner only'], correct: 'Project Manager', explain: 'BV owns value risk, SA owns solution-delivery risk, PM owns delivery-enablement risk (11.1).' },
      { id: 'F3Q47', topic: 'GV', q: 'Identify the missing word. When creating agile governance, it is important to focus on the [ ? ] behind the governance.', options: ['purpose', 'page count', 'job titles only', 'colour of the templates'], correct: 'purpose', explain: 'Design processes that support the purpose of governance without limiting agility (12.1).' },
      { id: 'F3Q48', topic: 'GV', q: 'For the Terms of Reference, which RACI pairing is correct?', options: ['R = Project Manager; A = Scrum Master', 'R = Business Visionary; A = Business Sponsor', 'R = Product Owner; A = Developers', 'R = Solution Architect; A = Project Manager'], correct: 'R = Business Visionary; A = Business Sponsor', explain: 'ToR: Responsible = Business Visionary; Accountable = Business Sponsor (Appendix A).' },
      { id: 'F3Q49', topic: 'GV', q: 'Which of the following can be customised to show regulatory compliance?\n1. Solution Architecture Definition\n2. Sprint Review Records\n3. Project Review Reports\n4. The Daily Scrum conversation itself, with no record', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'SAD, Sprint Review Records and Project Review Reports can be tailored as compliance evidence (12.2).' },
      { id: 'F3Q50', topic: 'GV', q: 'Consider the statements about the Cone of Uncertainty. Which is/are true?\n1. Early estimates are inherently vague\n2. Only after Foundations can Delivery Teams give more solid estimates', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Estimates tighten through the lifecycle; pre-Foundations figures are rough indicators (12.3.1).' },
    ],
  },
  {
    id: 'final4',
    title: 'Final Paper 4',
    questions: [
      { id: 'F4Q1', topic: 'KC', q: 'Identify the missing word. The Consortium says Business Agility is unlocked by inspiring people and harnessing their collaborative and [ ? ] working styles.', options: ['purely contractual', 'secretive', 'creative', 'command-driven'], correct: 'creative', explain: 'Business Agility harnesses collaborative and creative ways of working to meet the organisation\'s purpose (2.1.1).' },
      { id: 'F4Q2', topic: 'KC', q: 'Which of the following is NOT a reason AgilePM gives for needing agility in project delivery?', options: ['Legacy methods assume the problem will not change much during the project', 'Long-term detailed plans become outdated quickly in VUCA conditions', 'Heavy documents often expire before they are approved', 'VUCA disappears once a Gantt chart is published'], correct: 'VUCA disappears once a Gantt chart is published', explain: 'Publishing a plan does not remove VUCA; that is why agility is needed (2.1.2 / 2.4).' },
      { id: 'F4Q3', topic: 'KC', q: 'Which of the following is a listed advantage of an incremental approach to delivery?', options: ['Users should be kept away from the real product until the end', 'Documentation should describe an imagined future design rather than what was actually delivered', 'The organisation can gain value early', 'The business case must never be revisited'], correct: 'The organisation can gain value early', explain: 'Incremental delivery realises value early and documentation should reflect what was actually delivered (2.4.2).' },
      { id: 'F4Q4', topic: 'KC', q: 'Scrum is a poor fit for which kind of work?', options: ['Complex product work where the solution is not fully known', 'R&D and design problems needing iteration', 'Standardised or highly repetitive work that is already well defined', 'Collaborative content creation'], correct: 'Standardised or highly repetitive work that is already well defined', explain: 'Scrum fits complex, uncertain work; it is less suited to routine, well-defined repetitive tasks (2.2).' },
      { id: 'F4Q5', topic: 'KC', q: 'Identify the missing words. Completing detailed work at the last responsible moment is more efficient because near-future predictions are more [ ? ].', options: ['political', 'expensive', 'reliable', 'optional'], correct: 'reliable', explain: 'Later decisions benefit from learning and more reliable near-term information (2.4.2).' },
      { id: 'F4Q6', topic: 'SC', q: 'Empiricism in Scrum rests on which three pillars?\n1. Transparency\n2. Inspection\n3. Documentation\n4. Adaptation', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The pillars are Transparency, Inspection and Adaptation (3.2).' },
      { id: 'F4Q7', topic: 'SC', q: 'What happens if a Product Backlog item does not meet the Definition of Done by the end of the Sprint?', options: ['It may still be released if the Sponsor agrees verbally', 'It is automatically re-labelled as a Could Have', 'It cannot be released or presented at the Sprint Review and returns to the Product Backlog', 'It is added to the Management Approach Definition'], correct: 'It cannot be released or presented at the Sprint Review and returns to the Product Backlog', explain: 'Undone work is not part of the Increment and returns to the Product Backlog (3.6).' },
      { id: 'F4Q8', topic: 'SC', q: 'Consider the statements about Sprint rules. Which is/are true?\n1. No changes are made that would endanger the Sprint Goal\n2. Quality does not decrease during the Sprint', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Scope may be clarified with the Product Owner, but the Sprint Goal and quality are protected (3.5).' },
      { id: 'F4Q9', topic: 'SC', q: 'Identify the missing word. Ideas become value inside the Sprint, which Scrum calls its [ ? ].', options: ['audit', 'contract', 'portfolio', 'heartbeat'], correct: 'heartbeat', explain: 'The Sprint is the heartbeat of Scrum (3.5).' },
      { id: 'F4Q10', topic: 'SC', q: 'Which of the following are ways the Scrum Master serves the organisation?\n1. Leading, training and coaching Scrum adoption\n2. Helping stakeholders enact empirical approaches\n3. Removing barriers between stakeholders and Scrum Teams\n4. Ordering the Product Backlog instead of the Product Owner', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The Product Owner remains accountable for Product Backlog order (3.4).' },
      { id: 'F4Q11', topic: 'SC', q: 'During Topic Three of Sprint Planning, selected items are often decomposed into work items of what size?', options: ['One month or more', 'One calendar year', 'One Project Increment', 'One day or less'], correct: 'One day or less', explain: 'How-work is often broken into items of one day or less (3.5).' },
      { id: 'F4Q12', topic: 'AF', q: 'Which of the following are true about the four project variables?\n1. In AgilePM, Time, Cost and Quality are normally fixed\n2. In AgilePM, Features are the variable used for contingency\n3. In a traditional approach, Features are typically fixed\n4. AgilePM treats Quality as an accidental variable under schedule pressure', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'AgilePM protects Quality with a clear Definition of Done; it is not left as an accidental variable (4.2).' },
      { id: 'F4Q13', topic: 'AF', q: 'Creating a solid base before major build, then growing the solution in increments, is which numbered AgilePM principle?', options: ['Principle 4 — Never Compromise Quality', 'Principle 2 — Deliver on Time', 'Principle 8 — Demonstrate Control', 'Principle 5 — Build Incrementally from Firm Foundations'], correct: 'Principle 5 — Build Incrementally from Firm Foundations', explain: 'Principle 5 is Build Incrementally from Firm Foundations (4.3).' },
      { id: 'F4Q14', topic: 'AF', q: 'Consider the statements about Demonstrate Control. Which is/are true?\n1. Progress should be measured by working solutions rather than completed tasks alone\n2. A partially completed feature has more business value than a feature not started', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Incomplete work adds complication without value; an unstarted feature is preferable to a half-finished one (4.3).' },
      { id: 'F4Q15', topic: 'AF', q: 'Before major development starts, Principle 5 asks teams to understand which trio at a high level?', options: ['Holiday rota, office lease and brand palette', 'Supplier penalties, a full Gantt chart and a closed RAID log', 'Every test script, code module and user name', 'The business problem, the proposed solution and associated risk'], correct: 'The business problem, the proposed solution and associated risk', explain: 'Those three understandings form the firm foundations before major development (4.3).' },
      { id: 'F4Q16', topic: 'AF', q: 'Which principle requires documentation only when it adds value, helps development and support, or is essential for safety or regulation?', options: ['Deliver on Time', 'Never Compromise Quality', 'Focus on the Business Need', 'Communicate Continuously and Clearly'], correct: 'Communicate Continuously and Clearly', explain: 'Principle 7 sets those three conditions for creating documentation (4.3).' },
      { id: 'F4Q17', topic: 'IN', q: 'Which duties belong to the Project Champion who holds funding?\n1. Owning the Business Case\n2. Holding the project budget\n3. Estimating the size of every Product Backlog item\n4. Acting as final authority on critical project decisions', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'PBI sizing is a Delivery Team / refinement activity, not a Sponsor accountability (5.3).' },
      { id: 'F4Q18', topic: 'IN', q: 'Alongside Project and Delivery Team, what is the third AgilePM role category?', options: ['Shareholder', 'Auditor-only', 'Contractor', 'Advisor'], correct: 'Advisor', explain: 'The three categories are Project (outer), Delivery Team (inner) and Advisor (outside) (5.3).' },
      { id: 'F4Q19', topic: 'IN', q: 'Value ownership for a product is described as follows. Which is/are true?\n1. The Product Owner should be a committee so that no one person is accountable\n2. The entire organisation must respect the Product Owner\'s decisions for the role to succeed', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'The Product Owner is one person, not a committee, representing many stakeholders (3.4 / 5.3.5).' },
      { id: 'F4Q20', topic: 'IN', q: 'What do Business Advisors primarily do?', options: ['Replace the Business Visionary on every decision', 'Hold the project budget', 'Order the Sprint Backlog instead of the Developers', 'Collaborate with Value Ownership roles and give specialist business input'], correct: 'Collaborate with Value Ownership roles and give specialist business input', explain: 'Business Advisors support requirements, scenarios, testing and compliance from a business view (5.4).' },
      { id: 'F4Q21', topic: 'IN', q: 'Which of the following correctly describe the Scrum Master in AgilePM?\n1. The role corresponds with the earlier Team Leader role\n2. Together with the Project Manager, the Scrum Master facilitates cross-team planning, refinement and review\n3. The Scrum Master owns the Business Case\n4. Where teams share a Product Backlog, the Scrum Master helps each Product Increment meet a common Definition of Done', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Business Case is owned by the Business Sponsor / Value Ownership, not the Scrum Master (5.3.6).' },
      { id: 'F4Q22', topic: 'IN', q: 'Which of the following do agile leaders develop, rather than followers?', options: ['Larger steering packs', 'More templates', 'Longer contracts', 'New leaders'], correct: 'New leaders', explain: 'Agile leaders grow leadership in others rather than creating dependency (5.1).' },
      { id: 'F4Q23', topic: 'IN', q: 'Consider the statements about scaled Product Owners. Which is/are true?\n1. An experienced Product Owner may support more than one team if they share a single Product Backlog\n2. A new Business Ambassador would typically work with fewer teams, often just one', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Good practice allows an experienced PO up to about three teams on one backlog; novices take fewer (5.4).' },
      { id: 'F4Q24', topic: 'CC', q: 'Which of the following describes High Alignment and Low Autonomy on the Aligned Autonomy Matrix?', options: ['Innovative / collaborative culture', 'Authoritative organisation / authoritarian culture', 'Entrepreneurial / chaotic culture', 'Bureaucratic / indifferent culture'], correct: 'Authoritative organisation / authoritarian culture', explain: 'High alignment + low autonomy = authoritative; high + high = innovative (6.3).' },
      { id: 'F4Q25', topic: 'CC', q: 'Which of the following are communication choices AgilePM discusses?\n1. Replacing all talk with unread status reports\n2. Face-to-face conversation\n3. Instant messaging\n4. Collaborative workspaces', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Status-report-only communication is a failure mode, not a recommended choice (6.3).' },
      { id: 'F4Q26', topic: 'CC', q: 'Consider the statements about modelling. Which is/are true?\n1. Modelling is a method of visually representing a problem or solution\n2. Modelling is intended to replace all stakeholder conversation', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Modelling supports shared understanding; it does not replace conversation (6.4).' },
      { id: 'F4Q27', topic: 'CC', q: 'Identify the missing word. Over-using technology for communication can reduce effectiveness because body language and [ ? ] of voice are lost.', options: ['velocity', 'budget', 'MoSCoW', 'tone'], correct: 'tone', explain: 'Email and chat lack tone and body language, which increases misunderstanding (6.3).' },
      { id: 'F4Q28', topic: 'PR', q: 'Which optional milestone snapshot gathers Feasibility findings so decision-makers can judge whether to continue?', options: ['Sprint Backlog', 'Feasibility Assessment', 'Daily Scrum notes', 'Product Increment'], correct: 'Feasibility Assessment', explain: 'The Feasibility Assessment is an optional milestone snapshot for go/no-go governance (7.3 / Appendix A).' },
      { id: 'F4Q29', topic: 'PR', q: 'Which of the following are true about revisiting Foundations between Project Increments?\n1. It can re-establish firm foundations for the next increment\n2. It is forbidden once Delivery has started\n3. It can refresh tailoring decisions after PAQ review\n4. Fine detail for later increments can still be left until needed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Foundations may be revisited after each Project Increment on longer or more complex projects (7.4).' },
      { id: 'F4Q30', topic: 'PR', q: 'Consider the statements about Deployment. Which is/are true?\n1. Deployment should be ongoing in line with Delivery when incremental release is feasible\n2. If incremental delivery is not possible, Deployment can be a separate phase', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Deployment is preferably continuous, but may be a distinct phase when needed (7.6).' },
      { id: 'F4Q31', topic: 'PR', q: 'Identify the missing word. Pre-Project is not intended to prove the project is [ ? ]; it seeks approval for a small investment to explore further.', options: ['fully designed', 'funded forever', 'already deployed', 'feasible'], correct: 'feasible', explain: 'Feasibility comes next; Pre-Project only justifies investigating (7.2).' },
      { id: 'F4Q32', topic: 'PR', q: 'Who typically provides funding and support during Pre-Project, alongside a Business Visionary who shapes the vision?', options: ['Scrum Master', 'Business Sponsor', 'Process Advisor', 'Developer'], correct: 'Business Sponsor', explain: 'Pre-Project roles centre on the Business Visionary (vision) and Business Sponsor (funding) (7.2).' },
      { id: 'F4Q33', topic: 'ES', q: 'Which of the following are the three levels of User Story detail from broadest to most detailed?\n1. Epic / theme-level stories suitable for early phases\n2. Features or mid-level stories for increment planning\n3. Fine-grained stories ready for a Sprint\n4. The Management Approach Definition rewritten as a story', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'Detail emerges from epics through mid-level items to Sprint-ready stories (8.2.4).' },
      { id: 'F4Q34', topic: 'ES', q: 'Which of the following best describes how Acceptance Criteria are commonly expressed so they can be tested?', options: ['As a Management by Exception log', 'As a single Fibonacci card', 'As Parkinson\'s Law', 'As Given / When / Then scenarios'], correct: 'As Given / When / Then scenarios', explain: 'Scenario-style Given / When / Then criteria make confirmation testable (8.2).' },
      { id: 'F4Q35', topic: 'ES', q: 'MoSCoW labels are tied to a timeframe. Which is/are true?\n1. A requirement\'s priority at Project Increment level may differ from its priority at Sprint level\n2. Once labelled Must Have at project level, every child story is automatically a Sprint Must Have in every Sprint', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Priorities are timeframe-specific; a project Must may be split across increments and Sprints (9.8).' },
      { id: 'F4Q36', topic: 'ES', q: 'If almost every requirement is labelled Must Have, what is the usual planning consequence?', options: ['Feature contingency disappears and delivery risk rises', 'Velocity automatically doubles', 'The PAQ becomes optional', 'Quality can be safely ignored'], correct: 'Feature contingency disappears and delivery risk rises', explain: 'If everything is Must, there is no feature contingency (9.2).' },
      { id: 'F4Q37', topic: 'ES', q: 'How should estimates change as the lifecycle progresses?\n1. They become more precise as requirements become clearer\n2. They are frozen after Feasibility and must never change\n3. Feasibility figures are rough and based on limited information\n4. Delivery figures are updated using what has been learned', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Estimates evolve; they are not frozen at Feasibility (8.3).' },
      { id: 'F4Q38', topic: 'ES', q: 'Identify the missing words. A useful technique when assigning MoSCoW priorities is to ask whether the solution is still [ ? ] without the requirement.', options: ['viable', 'colourful', 'documented', 'outsourced'], correct: 'viable', explain: 'If the solution is not viable without it, the item is a true Must Have (9.5).' },
      { id: 'F4Q39', topic: 'PC', q: 'A useful Cross-Team Refinement session typically includes which of the following?\n1. Project Roles and Product Owner(s)\n2. Representatives of the Scrum / Delivery Teams\n3. The entire customer base in one room every day\n4. A shared view of dependencies and upcoming work', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'CTR uses project roles, team representatives and a shared dependency view — not the entire customer base daily (10.5).' },
      { id: 'F4Q40', topic: 'PC', q: 'The Required plan produced by the end of Foundations is described as follows. Which is/are true?\n1. It is an evolutionary Project Artifact\n2. It should define a high-level roadmap of increments and the next increment\'s Sprints', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The Delivery Plan is Required and evolutionary, remaining high-level (10.2 / Appendix A).' },
      { id: 'F4Q41', topic: 'PC', q: 'Identify the missing word. Management by Exception means only [ ? ] deviations are escalated.', options: ['major', 'cosmetic', 'email', 'colour'], correct: 'major', explain: 'Minor deviations stay with the team; major deviations (e.g. Sprint Goal at risk) escalate (10.4.2).' },
      { id: 'F4Q42', topic: 'PC', q: 'Who plays a key role during a Sprint ensuring Product and Solution Increments stay aligned?', options: ['External auditors only', 'The Solution Architect, guiding coherence across teams', 'The investment board chair', 'A random stakeholder from the Power/Interest grid'], correct: 'The Solution Architect, guiding coherence across teams', explain: 'The SA oversees coherence of the evolving solution across Delivery Teams (5.3 / 10.5).' },
      { id: 'F4Q43', topic: 'PC', q: 'After a Delivery Team finishes Sprint Planning, which artifact should exist?', options: ['The Terms of Reference', 'The Sprint Backlog, including the Sprint Goal', 'The Benefits Assessment', 'The Feasibility Assessment'], correct: 'The Sprint Backlog, including the Sprint Goal', explain: 'Sprint Planning produces the Sprint Backlog (why, what and how) (3.5 / 10.6).' },
      { id: 'F4Q44', topic: 'RK', q: 'Which of the following are types of constraint called out in PAQ Statement 17?\n1. The team\'s preferred snack\n2. Internal standards\n3. External regulatory standards\n4. Commercial arrangements', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'PAQ 17 considers internal standards, external regulation and commercial arrangements (11.2.2).' },
      { id: 'F4Q45', topic: 'RK', q: 'Consider the statements about agility in practice and risk. Which is/are true?\n1. How fully AgilePM guidance is followed influences the approach\'s intrinsic ability to deal with risk\n2. Simply naming the method AgilePM removes all VUCA risk automatically', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Effectiveness depends on how the approach is actually applied (11.1).' },
      { id: 'F4Q46', topic: 'RK', q: 'Identify the missing word. If the PAQ shows the project lacks a clear vision, the usual remedy is to define and [ ? ] that vision.', options: ['share', 'hide', 'auction', 'outsource'], correct: 'share', explain: 'An unclear vision is fixed by defining and communicating it; the PAQ is then reviewed again at the end of Foundations (11.2.1).' },
      { id: 'F4Q47', topic: 'GV', q: 'For the Solution Architecture Definition, which Responsible / Accountable pairing is correct?', options: ['R = Project Manager; A = Business Sponsor', 'R = Solution Architect; A = Business Visionary', 'R = Product Owner; A = Scrum Master', 'R = Developers; A = Process Advisor'], correct: 'R = Solution Architect; A = Business Visionary', explain: 'SAD: Responsible = Solution Architect; Accountable = Business Visionary (Appendix A).' },
      { id: 'F4Q48', topic: 'GV', q: 'Which of the following are true about Project Artifacts?\n1. Formality must always be maximised to prove agility\n2. Not every project needs every artifact\n3. Artifacts should only be produced if they help the people who will use them\n4. Users should be asked what information and format they need', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Create artifacts only if they add value; extra formality must not reduce agility (Appendix A).' },
      { id: 'F4Q49', topic: 'GV', q: 'Consider the statements about the Delivery Approach Definition. Which is/are true?\n1. The DAD is Optional\n2. Responsible is the Solution Architect and Accountable is the Project Manager', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'DAD is optional; R = SA, A = PM (Appendix A).' },
      { id: 'F4Q50', topic: 'GV', q: 'For financial governance, how does AgilePM recommend expressing estimates?', options: ['As ranges, not single figures', 'As slogans', 'As job titles', 'As a single figure chosen by the estimator'], correct: 'As ranges, not single figures', explain: 'Ranges communicate uncertainty; a Sponsor who wants one number must choose it (12.3.1).' },
    ],
  },
  {
    id: 'final5',
    title: 'Final Paper 5',
    questions: [
      { id: 'F5Q1', topic: 'KC', q: 'Which year was AgilePM first introduced by the DSDM Consortium?', options: ['1991', '1994', '2010', '2016'], correct: '2010', explain: 'AgilePM was introduced in 2010; DSDM itself dates from 1994 and the Consortium rebranded in 2016 (Ch.1).' },
      { id: 'F5Q2', topic: 'KC', q: 'Identify the missing word. Uncertainty in VUCA means it is hard to know what will happen or to make accurate [ ? ].', options: ['seating plans', 'timesheets', 'logos', 'predictions'], correct: 'predictions', explain: 'Uncertainty is the difficulty of knowing what will happen or predicting accurately (2.1.2).' },
      { id: 'F5Q3', topic: 'KC', q: 'Which of the following are enhanced Manifesto principles for the project context?\n1. Welcome change even late in the project\n2. Working solutions are the primary measure of progress\n3. Fix every requirement in a contract before Feasibility\n4. The best outcomes emerge from self-organising teams', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Fixing all requirements up front contradicts welcoming change and emerging detail (2.1.4).' },
      { id: 'F5Q4', topic: 'KC', q: 'Consider the statements about product management agility. Which is/are true?\n1. It is valuable only when the environment is already chaotic\n2. Even in more stable work it can improve communication, involvement and incremental benefits', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 2 is true', explain: 'Agility still helps communication, involvement and incremental benefit even when conditions are relatively stable (2.4.3).' },
      { id: 'F5Q5', topic: 'KC', q: 'AgilePM positions short-term delivery control and long-term product care as complementary. Which pairing matches that view?', options: ['PM ignores strategy while PLM ignores delivery dates', 'PLM replaces all project roles', 'The two disciplines are identical', 'Project management handles time-bound execution; PLM keeps long-term product focus'], correct: 'Project management handles time-bound execution; PLM keeps long-term product focus', explain: 'PM, PLM and AgilePM together align short-term delivery with long-term product value (2.3–2.4).' },
      { id: 'F5Q6', topic: 'SC', q: 'In four steps, Scrum is summarised as which repeating cycle?', options: ['Write a full specification, freeze it, then hand it to operations', 'Replace the Product Owner with a committee of Sponsors', 'Hold a yearly steering meeting and then deploy once', 'Order the work, create an Increment in a Sprint, inspect and adapt, then repeat'], correct: 'Order the work, create an Increment in a Sprint, inspect and adapt, then repeat', explain: 'The Scrum nutshell is order, deliver an Increment, inspect and adapt, repeat (3.1).' },
      { id: 'F5Q7', topic: 'SC', q: 'The fundamental Scrum unit contains which roles (and which extra title is an AgilePM addition)?\n1. Scrum Master\n2. Product Owner\n3. Developer\n4. Project Manager as a fourth Scrum role', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The Scrum Team is one Scrum Master, one Product Owner and Developers. The Project Manager is an AgilePM role, not a Scrum role (3.4).' },
      { id: 'F5Q8', topic: 'SC', q: 'Identify the missing word. Transparency without [ ? ] is misleading and wasteful.', options: ['a penalty clause', 'overtime', 'a Gantt baseline', 'inspection'], correct: 'inspection', explain: 'Transparency enables inspection; without inspection it is wasteful (3.2).' },
      { id: 'F5Q9', topic: 'SC', q: 'Consider the statements about the Sprint. Which is/are true?\n1. Sprints are fixed-length events of one month or less\n2. A new Sprint starts immediately after the previous one ends', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Sprints are consecutive timeboxes of one month or less (3.5).' },
      { id: 'F5Q10', topic: 'SC', q: 'On a one-month Sprint, which event is timeboxed to a maximum of four hours?', options: ['Daily Scrum', 'Sprint Retrospective', 'Sprint Review', 'Sprint Planning'], correct: 'Sprint Review', explain: 'Sprint Review is max 4 hours for a one-month Sprint (3.5).' },
      { id: 'F5Q11', topic: 'SC', q: 'Which commitment is attached to the Product Increment?', options: ['Product Goal', 'Sprint Goal', 'Definition of Done', 'Business Case'], correct: 'Definition of Done', explain: 'Increment → Definition of Done (3.6).' },
      { id: 'F5Q12', topic: 'AF', q: 'AgilePM contrasts common sense with which companion idea — adapting decisions to real situations instead of rigid procedure?', options: ['Parkinson\'s Law', 'Taylorism', 'Scope creep', 'Pragmatism'], correct: 'Pragmatism', explain: 'Pragmatism adapts decisions to real life; common sense avoids unnecessary complexity (4.1).' },
      { id: 'F5Q13', topic: 'AF', q: 'Which of these belong among the eight AgilePM principles rather than a documentation slogan?\n1. Focus on the Business Need\n2. Collaborate\n3. Maximise comprehensive documentation\n4. Communicate Continuously and Clearly', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'Documentation is just enough, not maximised (4.3).' },
      { id: 'F5Q14', topic: 'AF', q: 'Identify the missing words. Artificial deadlines that do not align with real business needs can be harmful if used only as a measure of [ ? ].', options: ['team learning', 'customer delight', 'technical excellence', 'success or control'], correct: 'success or control', explain: 'Principle 2 warns against artificial deadlines used only for control (4.3).' },
      { id: 'F5Q15', topic: 'AF', q: 'Consider the statements about how AgilePM helps Scrum roles. Which is/are true?\n1. AgilePM gives the Product Owner a business, user and corporate context for decisions\n2. AgilePM gives the Scrum Master a way to communicate with business leaders and project managers', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'AgilePM supplies project context the Scrum roles alone do not provide (4.4).' },
      { id: 'F5Q16', topic: 'AF', q: 'Which kind of work is cited as sitting more naturally with AgilePM than with Scrum used on its own?', options: ['Maintaining one team Product Backlog', 'Running a Daily Scrum', 'Business process change and other work not tied directly to building a product', 'Setting a Sprint Goal'], correct: 'Business process change and other work not tied directly to building a product', explain: 'AgilePM covers wider project and business-change work beyond a single product team (4.4).' },
      { id: 'F5Q17', topic: 'IN', q: 'Which Principle of Agile Leadership is demonstrated when emotion is harnessed as a driver of creativity?', options: ['Actions speak louder than words', 'Leaders devolve appropriate power and authority', 'Leadership lives everywhere in the organisation', 'Emotion is a foundation for enhanced creativity and innovation'], correct: 'Emotion is a foundation for enhanced creativity and innovation', explain: 'That principle recognises emotion as a foundation for creativity (5.1).' },
      { id: 'F5Q18', topic: 'IN', q: 'Which of the following correctly map roles to domains?\n1. Business Sponsor is Value Ownership\n2. Business Visionary is Value Ownership\n3. Solution Architect is Solution Delivery\n4. Project Manager is Value Ownership', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'The Project Manager sits in Delivery Enablement, not Value Ownership (5.3).' },
      { id: 'F5Q19', topic: 'IN', q: 'Consider the statements about the Business Visionary. Which is/are true?\n1. The Business Visionary may delegate Product Backlog work but remains accountable\n2. The Business Visionary owns the evolving Solution and collaborates with Product Owner(s) on Product Backlogs', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Delegation does not remove BV accountability for value and the Solution (5.3).' },
      { id: 'F5Q20', topic: 'IN', q: 'Identify the missing word. A Process Advisor typically collaborates with organisation-enablement roles; an Agile Coach or Workshop [ ? ] is a common example.', options: ['Contract', 'Sponsor', 'Increment', 'Facilitator'], correct: 'Facilitator', explain: 'Process Advisors include Agile Coaches and independent Workshop Facilitators (5.4).' },
      { id: 'F5Q21', topic: 'IN', q: 'Compared with the Business Visionary (value) and Solution Architect (integrity), the Project Manager decides which of the following?', options: ['Business-value trade-offs alone', 'Solution-architecture integrity alone', 'How the project is managed', 'Who may cancel a Sprint'], correct: 'How the project is managed', explain: 'PM: how the project is managed; BV: business value; SA: solution integrity (5.5).' },
      { id: 'F5Q22', topic: 'IN', q: 'Which of the following are Developer accountabilities in an AgilePM / Scrum team?\n1. Aiming to deliver a usable Product Increment each Sprint\n2. Deciding how the work will be done\n3. Owning the project budget\n4. Collaborating to a common Definition of Done when teams share a Product Backlog', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 4', explain: 'The Business Sponsor holds the budget; Developers decide how and deliver a usable increment (5.4).' },
      { id: 'F5Q23', topic: 'IN', q: 'On the leadership spectrum, which styles sit at the two ends described by AgilePM?', options: ['Servant leadership and command-and-control', 'Budget-holding and time-recording', 'Feasibility and Realisation', 'Must Have and Won\'t Have'], correct: 'Servant leadership and command-and-control', explain: 'Styles range from servant leadership to command-and-control; AgilePM encourages empowerment (5.1).' },
      { id: 'F5Q24', topic: 'CC', q: 'Working inside one group that uses each member\'s skills toward a shared goal is which form of collaboration?', options: ['Team collaboration', 'A supplier contract', 'A one-way status email', 'A steering-committee vote'], correct: 'Team collaboration', explain: 'Team collaboration is within a group; community collaboration unites all teams delivering value (6.2).' },
      { id: 'F5Q25', topic: 'CC', q: 'Which of the following should leaders do to build collaborative competence?\n1. Motivate people to ask for help\n2. Focus on blame when mistakes happen\n3. Embrace diverse skills and perspectives\n4. Practise active listening and promote it in the team', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Leaders focus on learning, not blame (6.2).' },
      { id: 'F5Q26', topic: 'CC', q: 'Identify the missing words. Documents should only be created when they provide [ ? ] and improve communication.', options: ['value', 'volume', 'vagueness', 'vendettas'], correct: 'value', explain: 'Create documents only when they add value (6.4).' },
      { id: 'F5Q27', topic: 'CC', q: 'Consider the statements about the Power/Interest Grid. Which is/are true?\n1. High power and high interest stakeholders should be closely engaged\n2. Low power and low interest stakeholders should be closely engaged in every decision', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Low/low stakeholders are monitored with minimum effort (6.3).' },
      { id: 'F5Q28', topic: 'PR', q: 'Once a Solution Increment is released into live use, AgilePM calls the resulting operational whole which of the following?', options: ['The Terms of Reference', 'A Won\'t Have list', 'The Sprint Backlog', 'The Deployed Solution'], correct: 'The Deployed Solution', explain: 'Deployment turns a Solution Increment into (or adds it to) the Deployed Solution (7.1).' },
      { id: 'F5Q29', topic: 'PR', q: 'Which of the following are timebox types AgilePM considers?\n1. Overall Project Timebox\n2. Project Increment Timebox\n3. Delivery Timeboxes (Sprints)\n4. Unlimited open-ended calendar with no end date', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 2, 3', explain: 'AgilePM uses nested project, increment and delivery timeboxes (7.1.2).' },
      { id: 'F5Q30', topic: 'PR', q: 'Consider the statements about the Delivery Phase. Which is/are true?\n1. It should aim to deliver a usable Product Increment each Sprint\n2. Delivering only a horizontal layer of technology is the preferred way to show value', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Only 1 is true', explain: 'Vertical slices of value are preferred; horizontal technical layers are discouraged (7.5 / 10.5).' },
      { id: 'F5Q31', topic: 'PR', q: 'Identify the missing word. Foundations focuses on three areas: Value, Solution and [ ? ].', options: ['Process', 'Penalties', 'Publicity', 'Parking'], correct: 'Process', explain: 'Foundations addresses Value, Solution and Process (7.4).' },
      { id: 'F5Q32', topic: 'PR', q: 'In a simple configuration without continuous release, Deployment ends when which of the following has happened?', options: ['The idea is first written down', 'The PAQ is opened for the first time', 'Feasibility has only just started', 'The planned Solution Increment is in the operating environment'], correct: 'The planned Solution Increment is in the operating environment', explain: 'Deployment completes when the increment is in live operation (or continuously as Delivery proceeds) (7.6).' },
      { id: 'F5Q33', topic: 'ES', q: 'A rolling record of how much work a team usually finishes in a Sprint is useful for forecasting. AgilePM treats that figure as which of the following?', options: ['The sole measure of delivery success', 'A count of artifacts produced', 'The Sponsor\'s overtime target', 'Velocity — a measure of output, not outcomes'], correct: 'Velocity — a measure of output, not outcomes', explain: 'Velocity is output, useful for forecasting, not the sole success measure (8.3).' },
      { id: 'F5Q34', topic: 'ES', q: 'Relative effort scoring (story points) is characterised by which of the following?\n1. It estimates relative effort rather than personal hours\n2. Each point equals the same elapsed hour for every person\n3. People of different skill levels can take part equally\n4. Planning Poker cards stay hidden until all are revealed', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Points are relative, not personal hours; simultaneous reveal reduces anchoring (8.3).' },
      { id: 'F5Q35', topic: 'ES', q: 'Identify the missing word. The people [ ? ] the work are responsible for estimating it.', options: ['doing', 'funding only', 'auditing only', 'avoiding'], correct: 'doing', explain: 'Those who will do the work estimate it (8.3).' },
      { id: 'F5Q36', topic: 'ES', q: 'Consider the statements about Functional and Non-Functional Requirements. Which is/are true?\n1. Functional requirements describe what the solution should do\n2. Non-functional requirements include qualities such as performance, security and usability', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'FRs are capabilities; NFRs are qualities and constraints, often reflected in the DoD (8.2.2).' },
      { id: 'F5Q37', topic: 'ES', q: 'Using the house-building teaching example, structural work in increment one is typically treated as which priority for that timeframe?', options: ['A Won\'t Have', 'An optional decoration', 'A Could Have that can be dropped with no impact', 'A Must Have for that increment, even if later rooms are Should or Could'], correct: 'A Must Have for that increment, even if later rooms are Should or Could', explain: 'Priorities are increment-specific; early structural work can be Must while later features are not (9.8).' },
      { id: 'F5Q38', topic: 'ES', q: 'Which of the following must be true for a Must Have in relation to other requirements?', options: ['It may depend on a Could Have that might be dropped', 'It must not depend on a Should Have or Could Have that could be dropped', 'It is optional if the Sponsor is busy', 'It is written only after Deployment'], correct: 'It must not depend on a Should Have or Could Have that could be dropped', explain: 'If a Must depends on a lower priority, that dependency is really a Must (9.5).' },
      { id: 'F5Q39', topic: 'PC', q: 'Which planning style has the Delivery Team forecast from capacity and then commit to a Sprint Goal it believes is achievable?', options: ['Sponsor-imposed hour targets with no discussion', 'Commitment-based planning', 'Planning only after deployment', 'Replacing the Daily Scrum with a monthly report'], correct: 'Commitment-based planning', explain: 'Commitment-based planning uses the team\'s forecast, not an imposed hour target (10.2 / 8.3).' },
      { id: 'F5Q40', topic: 'PC', q: 'If a team releases more than once inside a Sprint, which statements remain true?\n1. Those deployments should still be planned in Sprint Planning\n2. Continuous delivery forbids any Definition of Done\n3. More than one release per Sprint is allowed if that is the agreed approach\n4. A rollback option may be needed if a release causes problems', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '1, 3, 4', explain: 'Continuous delivery still requires Done quality and may include rollback (10.5).' },
      { id: 'F5Q41', topic: 'PC', q: 'At the end of a multi-team Sprint, the joint inspection event is described as follows. Which is/are true?\n1. Delivery Teams are represented\n2. The spirit is to inspect the integrated outcome and adapt, not to run a blame session', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'The Project Sprint Review inspects integrated progress across teams (10.5).' },
      { id: 'F5Q42', topic: 'PC', q: 'Identify the missing word. Outcome-based planning focuses on the valuable [ ? ] to be achieved, not on a complete task list invented too early.', options: ['outcome', 'overtime', 'org chart', 'office'], correct: 'outcome', explain: 'Outcome-based planning is one of the three planning concepts (10.1).' },
      { id: 'F5Q43', topic: 'PC', q: 'Developers keep the Sprint plan transparent by placing it where?', options: ['Only in a locked drawer in Finance', 'On a physical or digital board visible to the team', 'In the Terms of Reference appendix', 'In the Benefits Assessment'], correct: 'On a physical or digital board visible to the team', explain: 'The Sprint Backlog is a transparent plan, typically on a visible board (3.6 / 10.6).' },
      { id: 'F5Q44', topic: 'RK', q: 'VUCA-driven risk is handled inside AgilePM by which of the following means?\n1. Quality, risk and governance are left until after Deployment\n2. Philosophy, principles and practices guide value delivery\n3. Project Roles decide how best to apply the framework\n4. Workshops in Feasibility and Foundations address risks early', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Quality, risk and governance are considered from the outset, not after Deployment (11.1).' },
      { id: 'F5Q45', topic: 'RK', q: 'Consider PAQ Statement 13. Which is/are true?\n1. Developers are generally expected to work at a consistent level, often full-time, at least for a Project Increment\n2. Highly fragmented part-time allocation makes Sprint-based development harder', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'PAQ 13 expects consistent allocation sufficient to support Sprints (11.2.2).' },
      { id: 'F5Q46', topic: 'RK', q: 'Identify the missing word. If standards create obstacles, AgilePM suggests working with those who own the standards and building compliance into the Definition of [ ? ] and Acceptance Criteria.', options: ['Done', 'Holiday', 'Hierarchy', 'Delay'], correct: 'Done', explain: 'PAQ 17 remedies include building compliance into the DoD and Acceptance Criteria (11.2.2).' },
      { id: 'F5Q47', topic: 'GV', q: 'At Foundation level, Solution quality is first judged by which test?', options: ['Whether the Gantt chart is colour-coded', 'Whether the solution meets the business need and can remain reliable in use', 'Whether every Could Have was delivered', 'Whether the Daily Scrum lasted exactly 15 minutes'], correct: 'Whether the solution meets the business need and can remain reliable in use', explain: 'Solution quality starts with meeting the business need and remaining reliable over time (12.2).' },
      { id: 'F5Q48', topic: 'GV', q: 'Which of the following correctly state Responsible / Accountable pairs?\n1. Product Increment — R Business Sponsor, A Scrum Master\n2. Product Backlog — R Product Owner, A Business Visionary\n3. Sprint Backlog — R Developers, A Product Owner\n4. Solution Increment — R Project Organisation, A Business Visionary', options: ['1, 2, 3', '1, 2, 4', '1, 3, 4', '2, 3, 4'], correct: '2, 3, 4', explain: 'Product Increment is R = Delivery Team, A = Product Owner (Appendix A).' },
      { id: 'F5Q49', topic: 'GV', q: 'After the solution has been used in operation, benefits are recorded as follows. Which is/are true?\n1. The Benefits Assessment is a Recommended evolutionary artifact\n2. It explains how expected benefits have actually materialised', options: ['Only 1 is true', 'Only 2 is true', 'Both 1 and 2 are true', 'Neither 1 nor 2 is true'], correct: 'Both 1 and 2 are true', explain: 'Benefits Assessment records observed benefits after live use (Appendix A / 12.3.2).' },
      { id: 'F5Q50', topic: 'GV', q: 'RACI for the Delivery Approach Definition places Accountability with which role?', options: ['Business Visionary', 'Project Manager', 'Product Owner', 'Business Sponsor'], correct: 'Project Manager', explain: 'DAD: Responsible = Solution Architect; Accountable = Project Manager (Appendix A).' },
    ],
  },
]

